  CREATE TABLE "SBMO"."RX_PRINT_INFO" 
   (	"TENANT_ID" NUMBER(19,0) NOT NULL ENABLE, 
	"ID" NUMBER(19,0) NOT NULL ENABLE, 
	"PARTITION_STAMP" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"LABEL" CLOB NOT NULL ENABLE, 
	"PATIENT_ED" CLOB, 
	"CREATED_DATE" TIMESTAMP (6), 
	"FREE_FORM_REPORT_FORMAT" VARCHAR2(10), 
	"FREE_FORM_REPORT_MESSAGE" CLOB, 
