INSERT INTO ALL_TABLES (FILE_NAME,DDL_CLOB) VALUES
	 ('sbmo.rx_request_error.sql',TO_CLOB('
  CREATE TABLE "SBMO"."RX_REQUEST_ERROR" 
   (	"TENANT_ID" NUMBER NOT NULL ENABLE, 
	"ID" NUMBER NOT NULL ENABLE, 
	"DRUG_NAME" VARCHAR2(28) NOT NULL ENABLE, 
	"ORDER_TYPE" NUMBER NOT NULL ENABLE, 
	"STORE_NHINID" NUMBER NOT NULL ENABLE, 
	"ADDED_DATE" TIMESTAMP (6) NOT NULL ENABLE, 
	"NDC" VARCHAR2(11) NOT NULL ENABLE, 
	"STATUS" NUMBER, 
	"INVENTORY_NAME" VARCHAR2(255), 
	"ERROR_CODE" VARCHAR2(255), 
	"ERROR_MESSAGE" VARCHAR2(255), 
	"REQUEST_DECIMAL_QTY" FLOAT(126), 
	"REQUEST_QTY" NUMBER, 
	"RXNUM" VARCHAR2(16), 
	"STORE_CF_QUEUE_NUM" VARCHAR2(255), 
	"CREATED_DATE" TIMESTAMP (6), 
	"TXNUM" VARCHAR2(12), 
	"SPECIALTY" VARCHAR2(1), 
	"FACILITY_ID" NUMBER(19,0) NOT NULL ENABLE, 
	"INVENTORY_ID" NUMBER(38,0), 
	"VENDOR_ID" NUMBER(38,0), 
	 CONSTRAINT "RX_REQUEST_ERROR_PK" PRIMARY KEY ("TENANT_ID", "ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "SBMO_MULTITENANT_D"  ENABLE, 
	 SUPPLEMENTAL LOG DATA (ALL) COLUMNS, 
	 CONSTRAINT "RX_REQUEST_ERROR_FK2" FOREIGN KEY ("TENANT_ID", "FACILITY_ID")
	  REFERENCES "SBMO"."FACILITIES" ("TENANT_ID", "ID") ENABLE, 
	 CONSTRAINT "RX_REQUEST_ERROR_FK1" FOREIGN KEY ("TENANT_ID")
	  REFERENCES "SBMO"."TENANTS" ("ID") ENABLE, 
	 CONSTRAINT "RX_REQUEST_ERROR_FK3" FOREIGN KEY ("TENANT_ID", "INVENTORY_ID")
	  REFERENCES "SBMO"."INVENTORY" ("TENANT_ID", "ID") ENABLE, 
	 CONSTRAINT "RX_REQUEST_ERROR_FK4" FOREIGN KEY ("TENANT_ID", "VENDOR_ID")
	  REFERENCES "SBMO"."VENDOR" ("TENANT_ID", "ID") ENABLE
   ) PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "SBMO_MULTITENANT_D" 
  PARTITION BY LIST ("TENANT_ID") 
  SUBPARTITION BY RANGE ("CREATED_DATE") 
 (PARTITION "RXCOM"  VALUES (1) 
PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
